743	+        this.loading.set(false);
744	+      },
745	+      error: () => {
746	+        this.loading.set(false);
747	+        this.error.set('Warenkorb konnte nicht geladen werden.');
748	+      }
749	+    });
750	+  }
751	+
752	+  protected lineKey(productId: string, supplierId: string): string {
753	+    return `${productId}:${supplierId}`;
754	+  }
755	+
756	+  protected isBusy(productId: string, supplierId: string): boolean {
757	+    return this.busyKey() === this.lineKey(productId, supplierId);
758	+  }
759	+
760	+  protected updateQuantity(productId: string, supplierId: string, quantityRaw: string): void {
761	+    const cartId = this.cartService.cartId();
762	+    const quantity = Number(quantityRaw);
763	+    if (!cartId || !Number.isInteger(quantity) || quantity < 1) {
764	+      this.error.set('Bitte eine gültige Menge (mindestens 1) angeben.');
765	+      return;
766	+    }
767	+
768	+    this.busyKey.set(this.lineKey(productId, supplierId));
769	+    this.error.set(null);
770	+
771	+    this.cartApi.updateQuantity(cartId, productId, supplierId, quantity).subscribe({
772	+      next: (cart) => {
773	+        this.cart.set(cart);
774	+        this.busyKey.set(null);
775	+      },
776	+      error: (err: HttpErrorResponse) => {
777	+        this.busyKey.set(null);
778	+        this.error.set(err.status === 409 ? 'Angebot nicht mehr verfügbar' : 'Menge konnte nicht geändert werden.');
779	+      }
780	+    });
781	+  }
782	+
783	+  protected removeItem(productId: string, supplierId: string): void {
784	+    const cartId = this.cartService.cartId();
785	+    if (!cartId) {
786	+      return;
787	+    }
788	+
789	+    this.busyKey.set(this.lineKey(productId, supplierId));
790	+    this.error.set(null);
791	+
792	+    this.cartApi.removeItem(cartId, productId, supplierId).subscribe({
793	+      next: (cart) => {
794	+        this.cart.set(cart);
795	+        this.busyKey.set(null);
796	+      },
797	+      error: () => {
798	+        this.busyKey.set(null);
799	+        this.error.set('Position konnte nicht entfernt werden.');
800	+      }
801	+    });
802	+  }
803	+}
