9	    public async Task<CartResult?> AddItemAsync(
10	        Guid? cartId,
11	        string productId,
12	        string supplierId,
13	        int quantity,
14	        CancellationToken ct = default)
15	    {
16	        var offerExists = await context.Offers
17	            .AnyAsync(o => o.ProductId == productId && o.SupplierId == supplierId, ct);
18	        if (!offerExists)
19	        {
20	            return null;
21	        }
22	
23	        var resolvedCartId = cartId is not null && await context.Carts.AnyAsync(c => c.Id == cartId, ct)
24	            ? cartId.Value
25	            : await CreateCartAsync(ct);
26	
27	        var updatedRows = await context.CartItems
28	            .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
29	            .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);
30	
31	        if (updatedRows == 0)
32	        {
33	            var newItem = new CartItem { CartId = resolvedCartId, ProductId = productId, SupplierId = supplierId, Quantity = quantity };
34	            context.CartItems.Add(newItem);
35	            try
36	            {
37	                await context.SaveChangesAsync(ct);
38	            }
39	            catch (DbUpdateException)
40	            {
41	                // Ein gleichzeitiges Hinzufügen desselben Produkt-Lieferant-Paars zu
42	                // diesem Warenkorb hat seine Zeile zwischen unserem ExecuteUpdateAsync
43	                // (traf nichts) und diesem Add eingefügt — der DB-Unique-Constraint
44	                // (zusammengesetzter Primärschlüssel, AD-1) lehnt unseren Insert ab,
45	                // statt still zu duplizieren. Fallback: Update, das jetzt garantiert
46	                // genau diese Zeile trifft. Identisches Muster wie RatingService
47	                // (Story 2.3) für den AD-5-Race.
48	                context.Entry(newItem).State = EntityState.Detached;
49	                var raceFallbackRows = await context.CartItems
50	                    .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
51	                    .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);
52	
53	                if (raceFallbackRows == 0)
54	                {
55	                    throw;
56	                }
57	            }
58	        }
59	
60	        return await BuildCartResultAsync(resolvedCartId, ct);
61	    }
62	
63	    private async Task<Guid> CreateCartAsync(CancellationToken ct)
64	    {
65	        var cart = new Cart { Id = Guid.NewGuid() };
66	        context.Carts.Add(cart);
67	        await context.SaveChangesAsync(ct);
68	        return cart.Id;
69	    }
