71	    private async Task<CartResult> BuildCartResultAsync(Guid cartId, CancellationToken ct)
72	    {
73	        var lines = await context.CartItems
74	            .Where(ci => ci.CartId == cartId)
75	            .Join(context.Offers,
76	                ci => new { ci.ProductId, ci.SupplierId },
77	                o => new { o.ProductId, o.SupplierId },
78	                (ci, o) => new CartResultLine
79	                {
