82	                    SupplierId = ci.SupplierId,
83	                    SupplierName = o.Supplier!.Name,
84	                    Quantity = ci.Quantity,
85	                    UnitPrice = o.Price
86	                })
87	            .ToListAsync(ct);
88	
89	        return new CartResult
90	        {
91	            CartId = cartId,
92	            Items = lines,
93	            TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
94	        };
95	    }
