97	    public async Task<CartResult> GetCartAsync(Guid? cartId, CancellationToken ct = default)
98	    {
99	        if (cartId is null || !await context.Carts.AnyAsync(c => c.Id == cartId, ct))
100	        {
101	            return new CartResult { CartId = null, Items = [], TotalPrice = 0 };
102	        }
103	
104	        return await BuildCartResultAsync(cartId.Value, ct);
105	    }
