130	            .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, quantity), ct);
131	
132	        return new CartMutationResult
133	        {
134	            Status = CartMutationStatus.Success,
135	            Cart = await BuildCartResultAsync(cartId, ct)
136	        };
137	    }
